import mongoose from 'mongoose';
import { PROJECT_STATUS, PROJECT_STATUS_LIST } from '../config/constants.js';

const projectSchema = new mongoose.Schema(
  {
    // Generated by the server, e.g. SGC-2026-001 (utils/idGenerator.js)
    projectCode: { type: String, required: true, unique: true, uppercase: true, trim: true },
    name: { type: String, required: true, trim: true, maxlength: 150 },
    description: { type: String, trim: true, maxlength: 2000 },

    address: {
      line1: { type: String, required: true, trim: true, maxlength: 200 },
      city: { type: String, trim: true, maxlength: 80 },
      state: { type: String, trim: true, maxlength: 80 },
      pincode: { type: String, trim: true, maxlength: 10 },
    },

    // Site location for GPS attendance validation
    siteLocation: {
      latitude: { type: Number, min: -90, max: 90 },
      longitude: { type: Number, min: -180, max: 180 },
      radiusMeters: { type: Number, min: 10, max: 5000, default: 150 },
    },

    customer: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true, index: true },

    // Amounts in rupees. The service layer rounds to 2 decimals.
    budget: { type: Number, required: true, min: 0 },
    contractValue: { type: Number, required: true, min: 0 },

    startDate: { type: Date, required: true },
    expectedEndDate: { type: Date, required: true },
    actualEndDate: Date,

    status: {
      type: String,
      enum: PROJECT_STATUS_LIST,
      default: PROJECT_STATUS.PLANNING,
      index: true,
    },
    progressPercent: { type: Number, min: 0, max: 100, default: 0 },

    isArchived: { type: Boolean, default: false, index: true },
    archivedAt: Date,

    createdBy: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
    updatedBy: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  },
  { timestamps: true }
);

projectSchema.pre('validate', function (next) {
  if (this.startDate && this.expectedEndDate && this.expectedEndDate < this.startDate) {
    this.invalidate('expectedEndDate', 'Expected completion date cannot be before the start date');
  }
  const loc = this.siteLocation;
  if (loc && (loc.latitude == null) !== (loc.longitude == null)) {
    this.invalidate('siteLocation', 'Provide both latitude and longitude, or neither');
  }
  next();
});

// Indexes for list filters, sorting and search
projectSchema.index({ isArchived: 1, status: 1, createdAt: -1 });
projectSchema.index({ customer: 1, isArchived: 1 });
projectSchema.index({ expectedEndDate: 1, status: 1 });
projectSchema.index(
  { name: 'text', projectCode: 'text', 'address.line1': 'text', 'address.city': 'text' },
  { name: 'project_text_search' }
);

projectSchema.set('toJSON', {
  transform: (_doc, ret) => {
    delete ret.__v;
    return ret;
  },
});

export default mongoose.model('Project', projectSchema);